window.HOEREN_TESTS[89] = {"id":"im-sportgeschaeft","name":"Im Sportgeschäft","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Großer Saisonverkauf im Sportgeschäft. Alle Skier und Snowboards sind jetzt 40 Prozent günstiger, der Winter ist ja fast vorbei. Die neue Sommerware wie Fahrräder und Schwimmsachen ist aber nicht reduziert, nur Skier und Snowboards. Greifen Sie schnell zu, das Angebot gilt bis Sonntag. Viel Spaß beim Sport!","gender":"f","q":"Was ist im Angebot?","opts":["Fahrräder.","Skier und Snowboards.","Schwimmsachen."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Ich fange mit dem Joggen an und brauche die richtige Ausrüstung. Im Sportgeschäft kann man die Laufschuhe auf einem Laufband testen, das ist super. Aber ich brauche auch eine Jacke gegen Regen. Kommst du mit und berätst mich? Ruf zurück, danke dir!","gender":"m","q":"Mit welchem Sport fängt Markus an?","opts":["Schwimmen.","Joggen.","Radfahren."],"correct":1},{"transcript":"Achtung Kunden: Wir reparieren jetzt auch Fahrräder in unserer Werkstatt. Ob platter Reifen, kaputte Bremse oder Kette — bringen Sie Ihr Rad vorbei. Kleine Reparaturen machen wir sofort, größere dauern ein bis zwei Tage. Auch eine Inspektion vor dem Frühling bieten wir an. Fragen Sie unsere Mechaniker!","gender":"m","q":"Was bietet das Geschäft jetzt neu an?","opts":["Fahrradreparaturen.","Schwimmkurse.","Ski-Verleih."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Hey, ich habe mir endlich neue Wanderschuhe gekauft! Wir wollen doch im Sommer in die Berge. Der Verkäufer hat gesagt, ich soll sie vorher zu Hause einlaufen, sonst gibt es Blasen. Hast du schon deine Ausrüstung? Wir müssen das bald planen. Melde dich, bis bald!","gender":"f","q":"Was hat Anna gekauft?","opts":["Laufschuhe.","Fußballschuhe.","Wanderschuhe."],"correct":2},{"transcript":"Liebe Kunden: Wir verleihen Sportausrüstung für den Urlaub. Skier, Snowboards und sogar Wanderstöcke können Sie für eine Woche mieten, statt sie teuer zu kaufen. Das ist ideal, wenn Sie nur einmal im Jahr fahren. Buchen Sie früh, in den Ferien ist viel los. Wir beraten Sie gern!","gender":"f","q":"Was kann man im Geschäft mieten?","opts":["Fahrräder zum Behalten.","Autos.","Sportausrüstung."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Wir brauchen Sachen für den Urlaub. Hast du den Zettel aus der Küche?"},{"speaker":"Lisa","gender":"f","text":"Er steckt in meiner Tasche. Fünf Leute wollen etwas und das Geld reicht nicht für alles."},{"speaker":"Lukas","gender":"m","text":"Ich kaufe ein Fahrrad. Das alte ist kaputt und der Weg zur Arbeit ist weit."},{"speaker":"Lisa","gender":"f","text":"Die stehen links an der Wand. Braucht jemand einen Helm für das Rad?"},{"speaker":"Lukas","gender":"m","text":"Einen Helm kauft keiner. Wir haben zu Hause schon zwei."},{"speaker":"Lisa","gender":"f","text":"Ich kaufe eine Schwimmbrille für den See."},{"speaker":"Lukas","gender":"m","text":"Nimmst du die dunkle? Tom fährt im Winter in die Berge."},{"speaker":"Lisa","gender":"f","text":"Tom kauft Skier. Er braucht sie für den vielen Schnee."},{"speaker":"Lukas","gender":"m","text":"Die hängen ganz hinten. Will jemand Hanteln für das Wohnzimmer?"},{"speaker":"Lisa","gender":"f","text":"Hanteln will auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara läuft gern auf langen Wegen."},{"speaker":"Lisa","gender":"f","text":"Sara kauft Wanderschuhe. Im Herbst ist der Boden im Wald oft nass."},{"speaker":"Lukas","gender":"m","text":"Die braunen sind fest. Tim spielt jeden Samstag auf dem Platz."},{"speaker":"Lisa","gender":"f","text":"Tim kauft einen Fußball. Der alte ist weich und springt nicht mehr."},{"speaker":"Lukas","gender":"m","text":"Der liegt unten neben der Tür."},{"speaker":"Lisa","gender":"f","text":"Ich bringe den Zettel zur Kasse."}],"options":[{"letter":"a","text":"Yogamatte"},{"letter":"b","text":"Fahrrad"},{"letter":"c","text":"Helm"},{"letter":"d","text":"Fußball"},{"letter":"e","text":"Wanderschuhe"},{"letter":"f","text":"Tennisschläger"},{"letter":"g","text":"Hanteln"},{"letter":"h","text":"Schwimmbrille"},{"letter":"i","text":"Skier"}],"items":[{"person":"Lukas","correct":"b"},{"person":"Lisa","correct":"h"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Was kostet dieses Fahrrad? Ist Licht und Schloss dabei, oder ein Helm, oder eine Tasche?"},{"speaker":"Verkäufer","gender":"m","text":"499 Euro, mit Licht und Schloss. Helm und Tasche sind nicht dabei."},{"speaker":"Kunde","gender":"m","text":"Ist ein Helm dabei? Oder nur Licht und Schloss, ohne Tasche?"},{"speaker":"Verkäufer","gender":"m","text":"Nein, der Helm kostet extra, und eine Tasche auch. Dabei sind Licht und Schloss."},{"speaker":"Kunde","gender":"m","text":"Verstehe, Licht und Schloss ja, Helm und Tasche extra. Danke."}],"q":"Was ist beim Fahrrad dabei?","opts":["Eine Tasche.","Ein Helm.","Licht und Schloss."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Ich suche Laufschuhe. Ich laufe nicht auf der Straße und nicht im Fitnessstudio."},{"speaker":"Verkäuferin","gender":"f","text":"Laufen Sie auf der Straße oder im Wald? Im Fitnessstudio brauchen Sie andere Schuhe."},{"speaker":"Kundin","gender":"f","text":"Meistens im Wald. Also nicht Straße, nicht Studio."},{"speaker":"Verkäuferin","gender":"f","text":"Dann brauchen Sie ein festeres Modell für den Wald, nicht für die Straße und nicht fürs Studio."},{"speaker":"Kundin","gender":"f","text":"Gut, dann das Modell für den Wald. Danke."}],"q":"Wo läuft die Kundin meistens?","opts":["Auf der Straße.","Im Fitnessstudio.","Im Wald."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Können Sie mein Fahrrad reparieren? Der Reifen ist gut, das Licht auch."},{"speaker":"Mechaniker","gender":"m","text":"Was ist denn kaputt? Reifen und Licht kann ich auch machen, aber was genau?"},{"speaker":"Mann","gender":"m","text":"Die Bremse funktioniert nicht. Nicht der Reifen und nicht das Licht."},{"speaker":"Mechaniker","gender":"m","text":"Das mache ich gleich, in 20 Minuten. Die Bremse, nicht Reifen oder Licht."},{"speaker":"Mann","gender":"m","text":"Super, dann warte ich hier. Danke."}],"q":"Was ist am Fahrrad kaputt?","opts":["Der Reifen.","Die Bremse.","Das Licht."],"correct":1},{"lines":[{"speaker":"Kundin","gender":"f","text":"Kann ich die Skier auch mieten? Pro Tag 15 Euro, oder 80, oder 10?"},{"speaker":"Verkäufer","gender":"m","text":"Ja, 15 Euro pro Tag. 10 Euro wäre zu wenig, 80 Euro ist der Wochenpreis."},{"speaker":"Kundin","gender":"f","text":"Und für eine Woche? Nicht 15 pro Tag und nicht 10?"},{"speaker":"Verkäufer","gender":"m","text":"Eine Woche 80 Euro. Pro Tag bleiben 15 Euro, nicht 10 und nicht 80 am Tag."},{"speaker":"Kundin","gender":"f","text":"Dann miete ich eine Woche für 80 Euro. Danke."}],"q":"Was kostet das Mieten der Skier pro Tag?","opts":["15 Euro.","80 Euro.","10 Euro."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Mein Sohn braucht Fußballschuhe, nicht Laufschuhe und nicht Wanderschuhe."},{"speaker":"Verkäuferin","gender":"f","text":"Welche Größe? Laufschuhe und Wanderschuhe haben wir auch, aber Sie wollen Fußballschuhe."},{"speaker":"Vater","gender":"m","text":"Größe 36. Also wirklich Fußballschuhe, keine Laufschuhe."},{"speaker":"Verkäuferin","gender":"f","text":"Die haben wir, kommen Sie mit. Fußballschuhe Größe 36, nicht Laufschuhe, nicht Wanderschuhe."},{"speaker":"Vater","gender":"m","text":"Perfekt, dann nehmen wir die Fußballschuhe. Danke."}],"q":"Welche Schuhe braucht der Sohn?","opts":["Fußballschuhe.","Laufschuhe.","Wanderschuhe."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Walter, einer Verkäuferin im Sportgeschäft. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Walter, treiben heute mehr Menschen Sport als früher?"},{"speaker":"Walter","gender":"f","text":"Ja, eindeutig. Das Bewusstsein für Gesundheit ist gewachsen. Besonders Laufen und Radfahren sind beliebt, weil man sie überall machen kann, ohne teures Studio. Wir verkaufen heute viel mehr Laufschuhe als vor zehn Jahren. Das freut mich, denn Bewegung tut allen gut."},{"speaker":"Reporter","gender":"m","text":"Was ist der häufigste Fehler beim Kauf von Ausrüstung?"},{"speaker":"Walter","gender":"f","text":"Die Leute kaufen das Teuerste, weil sie denken, dann sind sie automatisch gute Sportler. Aber der teuerste Schuh hilft nichts, wenn er nicht zum Fuß passt. Wichtiger als der Preis ist die richtige Beratung. Ich frage immer zuerst, was der Kunde wirklich vorhat."},{"speaker":"Reporter","gender":"m","text":"Kaufen auch viele Anfänger bei Ihnen?"},{"speaker":"Walter","gender":"f","text":"Sehr viele, gerade im Januar nach den guten Vorsätzen. Das Problem ist: Viele kaufen teure Sachen und hören nach drei Wochen wieder auf. Mein Rat an Anfänger: Fangen Sie einfach an, mit wenig Ausrüstung. Wenn Sie dabei bleiben, können Sie immer noch mehr kaufen."},{"speaker":"Reporter","gender":"m","text":"Lohnt es sich, Ausrüstung zu mieten statt zu kaufen?"},{"speaker":"Walter","gender":"f","text":"Auf jeden Fall, wenn man einen Sport nur selten macht. Wer einmal im Jahr Ski fährt, muss keine teuren Skier kaufen. Mieten ist günstiger und spart Platz zu Hause. Auch zum Ausprobieren ist es ideal. Erst mieten, und wenn es Spaß macht, dann kaufen. Das rate ich oft."},{"speaker":"Reporter","gender":"m","text":"Was wünschen Sie sich von Ihren Kunden?"},{"speaker":"Walter","gender":"f","text":"Dass sie sich Zeit nehmen und sich beraten lassen. Gute Ausrüstung schützt vor Verletzungen, das ist kein Luxus. Und dass sie wirklich Sport treiben, nicht nur die schönen Sachen im Schrank liegen lassen. Bewegung macht glücklich und gesund. Dafür arbeite ich gern in diesem Geschäft."}],"items":[{"q":"Sie findet, der teuerste Schuh ist immer der beste.","correct":"nein"},{"q":"Laufen und Radfahren sind laut Frau Walter besonders beliebt.","correct":"ja"},{"q":"Viele Anfänger kaufen im Januar Sportausrüstung.","correct":"ja"},{"q":"Sie meint, Mieten lohnt sich bei selten ausgeübten Sportarten.","correct":"ja"},{"q":"Sie rät, sich beim Kauf keine Zeit zu nehmen.","correct":"nein"}]}]};
